public static int findNthLeapYear(int Y, int N) {
  if (Y < 1 || N < 1) {
    throw new IllegalArgumentException("Y and N should be positive integers.");
  }

  int nLeapYears = 0;
  for (int i = Y; i <= Y + N - 1; i++) {
    if (isLeapYear(i)) {
      nLeapYears++;
      if (nLeapYears == N) {
        return i;
      }
    }
  }

  throw new IllegalArgumentException("Cannot find Nth leap year.");
}

