public static int findNthLeapYear(int Y, int N) {
    // Calculate the number of leap years between Y and 1970
    int leapYears = (Y - 1970) / 4;
    // Calculate the Nth leap year after Y
    int nthLeapYear = Y + (N - 1) * 4 + (leapYears + 1) * 4;
    // Check if the Nth leap year is a leap year
    if (Math.abs(nthLeapYear - 1970) % 4 == 0) {
        return nthLeapYear;
    } else {
        throw new RuntimeException("Invalid input: Nth leap year is not a leap year");
    }
}

