public static int calculateTimeNeeded(int N) {
if (N <= 0) {
throw new IllegalArgumentException("Number of people must be greater than 0");
}

int timeNeeded = 0;

// Calculate the time needed to reverse the seating order
for (int i = 0; i < N; i++) {
timeNeeded++;

// Check if i is odd or even
if (i % 2 == 0) {
// If i is even, the person who was originally on their left
// is now on their right, so no change in position
// If i is odd, the person who was originally on their right
// is now on their left, so subtract 0.5
if (i % 2 == 1) {
timeNeeded -= 0.5;
}
}
}

// Return the time needed in minutes
return (int) (timeNeeded * 60);
}

