public int findLargestSubstring(List<String> strings) {

  Set<String> stringSet = new HashSet<>(strings); // Store the input list of strings as a set for efficient search

  // Initialize the largest substring and its length
  int longestSubstring = 0;
  int longestSubstringLength = 0;

  for (int i = 0; i < strings.size(); i++) {

    // Get the current string
    String string = strings.get(i);

    // Find the length of the current string
    int stringLength = string.length();

    // Check if the current string is the longest substring
    if (stringLength > longestSubstringLength) {
      longestSubstring = i;
      longestSubstringLength = stringLength;
    }

    // Check if the inverse of the current string is the longest substring
    int inverseStringLength = stringLength / 2;
    if (inverseStringLength > longestSubstringLength && string.substring(0, inverseStringLength).equals(string.substring(inverseStringLength))) {
      longestSubstring = i;
      longestSubstringLength = inverseStringLength;
    }

    // Check if any of the other strings contains the current string or its inverse
    for (int j = 0; j < strings.size(); j++) {
      if (j != i && strings.get(j).contains(string) || strings.get(j).contains(string.substring(0, inverseStringLength))) {
        longestSubstring = i;
        longestSubstringLength = stringLength;
        break;
      }
    }

  }

  // Return the index of the longest substring
  return longestSubstring;

