    if (strings == null || strings.size() == 0) {
        return -1;
    }

    // Create a hash set to store unique strings
    Set<String> stringSet = new HashSet<String>();
    stringSet.addAll(strings);

    // Initialize largest substring and its inverse
    String largestSubstring = "";
    String smallestSubstring = "";

    // Iterate over the strings
    for (String string : stringSet) {
        // Check for substring
        if (string.contains(largestSubstring)) {
            // Update largest substring
            largestSubstring = string;
        } else if (string.contains(smallestSubstring)) {
            // Update smallest substring
            smallestSubstring = string;
        }
    }

    // Return the largest substring if not empty, otherwise return the smallest substring
