public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
if (n <= 0 || start.length != 2 || end.length != 2 || paths.length != 2 * (n - 1) || paths[0].length != 2 || paths[1].length != 2) {
return "cannot be travelled";
}

HashMap<Integer, HashSet<Integer>> graph = new HashMap<>();

for (int[] path : paths) {
int start = path[0];
int end = path[1];
if (start < 0 || end < 0 || start >= n || end >= n) {
return "cannot be travelled";
}

HashSet<Integer> neighbors = graph.getOrDefault(start, new HashSet<>());
neighbors.add(end);
graph.put(start, neighbors);
}

boolean[] visited = new boolean[n];
Stack<Integer> stack = new Stack<>();
stack.push(start[0]);
visited[start[0]] = true;

while (!stack.isEmpty()) {
int current = stack.pop();
if (current == end[0]) {
return "can be travelled";
}

HashSet<Integer> neighbors = graph.get(current);
for (int neighbor : neighbors) {
if (!visited[neighbor]) {
visited[neighbor] = true;
stack.push(neighbor);
}
}
}

return "cannot be travelled";
}

