public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {

    // Check if the starting and ending n-tersections are valid
    if (start[0] >= n || start[1] >= n || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the paths are valid
    for (int[] path : paths) {
        if (path[0] >= n || path[1] >= n) {
            return "cannot be travelled";
        }
    }

    // Create a representation of visited n-tersections
    boolean[][] visited = new boolean[n][n];

    // Queue to store n-tersections to be visited
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.offer(start);

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Loop until the end n-tersection is reached
    while (!queue.isEmpty()) {
        // Get the next n-tersection to be visited from the queue
        int[] current = queue.poll();

        // Check if the current n-tersection is the end n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Add the neighboring n-tersections to the queue
        for (int[] path : paths) {
            int[] neighbor = {current[0] + path[0], current[1] + path[1]};

            // Check if the neighbor is a valid n-tersection
            if (neighbor[0] >= 0 && neighbor[0] < n && neighbor[1] >= 0 && neighbor[1] < n) {
                // Check if the neighbor has not been visited
                if (!visited[neighbor[0]][neighbor[1]]) {
                    // Mark the neighbor as visited
                    visited[neighbor[0]][neighbor[1]] = true;

                    // Add the neighbor to the queue
                    queue.offer(neighbor);
                }
            }
        }
    }

    // If the end n-tersection is not reached, return "cannot be travelled"
    return "cannot be travelled";
}

