public int[] twoSum(int[] nums, int target) {
    // Hash Map to store the indices of the nums array
    Map<Integer, Integer> indexMap = new HashMap<>();

    // Loop through the nums array
    for (int i = 0; i < nums.length; i++) {
        // If the target is equal to the current element
        // plus the sum of the indices, return the indices
        if (target == nums[i] + nums[indexMap.get(nums[i])]) {
            return new int[] {i, indexMap.get(nums[i])};
        }

        // If the target is not equal to the current element
        // plus the sum of the indices, add the current element
        // and its index to the Hash Map
        else {
            indexMap.put(nums[i], i);
        }
    }

    // Return an empty array if no indices are found
    return new int[] {};
}

