public boolean canArrange(int[] arr, int k) {
    // Check if the input array is not null and has even length
    if (arr == null || arr.length % 2 != 0) {
        throw new IllegalArgumentException("Invalid input array");
    }

    // Check if the divisor is not zero
    if (k == 0) {
        throw new IllegalArgumentException("Divisor cannot be zero");
    }

    // Create a hash map to store the counts of each number in the array
    Map<Integer, Integer> numCounts = new HashMap<>();
    for (int num : arr) {
        if (numCounts.containsKey(num)) {
            numCounts.put(num, numCounts.get(num) + 1);
        } else {
            numCounts.put(num, 1);
        }
    }

    // Check if the divisor is a factor of each number in the array
    for (int num : numCounts.keySet()) {
        if (num % k != 0) {
            return false;
        }
    }

    // Check if there are enough numbers in the array to divide it into n/2 pairs
    int numPairs = numCounts.size() / 2;
    for (int i = 0; i < numPairs; i++) {
        int num1 = numCounts.keySet().stream().skip(i * 2).findFirst().get();
        int num2 = numCounts.keySet().stream().skip(i * 2 + 1).findFirst().get();
        if (num1 % k != 0 || num2 % k != 0) {
            return false;
        }
    }

    return true;
}

