public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[] {1, 1};
    int i = 2;
    while (i < k) {
        fib[i] = fib[i - 1] + fib[i - 2];
        i++;
    }

    List<Integer> fibNumbers = new ArrayList<>();
    while (k > 0) {
        for (i = fib.length - 1; i >= 0; i--) {
            if (k - fib[i] >= 0) {
                k -= fib[i];
                fibNumbers.add(fib[i]);
                break;
            }
        }
    }

    return fibNumbers.size();
}

