            if ((Character.isUpperCase(s.charAt(i)) && Character.isUpperCase(s.charAt(i + 1))) ||
                    (Character.isLowerCase(s.charAt(i)) && Character.isLowerCase(s.charAt(i + 1)))) {
                continue;
