public int maxUniqueSplit(String s) {

// Check if the input string is null or empty
if (s == null || s.isEmpty()) {
return 0;
}

// Create a set to keep track of unique substrings
Set<String> uniqueSubstrings = new HashSet<>();

// Initialize the maximum number of unique substrings to 0
int maxUniqueSubstrings = 0;

// Loop through the string and split it into substrings
for (int i = 0; i < s.length(); i++) {

// Find the index of the next space character
int spaceIndex = s.indexOf(" ", i);

// If no space character is found, add the remaining substring and break the loop
if (spaceIndex < 0) {
uniqueSubstrings.add(s.substring(i));
break;
}

// Add the substring between the current index and the space index to the set
uniqueSubstrings.add(s.substring(i, spaceIndex));

// Update the maximum number of unique substrings
maxUniqueSubstrings = Math.max(maxUniqueSubstrings, uniqueSubstrings.size());

// Update the current index
i = spaceIndex + 1;
}

// Return the maximum number of unique substrings
return maxUniqueSubstrings;
}

