public int minOperations(String[] logs) {
    // Initialize variables to keep track of the current depth and the minimum number of steps
    int currentDepth = 0;
    int minSteps = 0;

    // Iterate through the logs and evaluate the corresponding operation
    for (String log : logs) {
        // If the log is a directory operation (i.e., it ends with '/'), increment the current depth
        if (log.endsWith("/")) {
            currentDepth++;
        // Otherwise, if the log is a return operation (i.e., it is '../'), decrement the current depth
        } else if (log.equals("../")) {
            currentDepth--;
        }

        // Keep track of the minimum number of steps required to return to the main folder
        minSteps = Math.min(minSteps, currentDepth);
    }

    return minSteps;
}

