public static String reverseWords(String s) {
    // Split the input string into an array of words using spaces as delimiters
    String[] words = s.split(" ");

    // Create a new string builder to store the reversed words
    StringBuilder sb = new StringBuilder();

    // Iterate over the array of words
    for (int i = 0; i < words.length; i++) {
        // Reverse the current word
        String word = new StringBuilder(words[i]).reverse().toString();

        // Add the reversed word to the string builder
        sb.append(word);

        // Add a space if there are more words to come
        if (i < words.length - 1) {
            sb.append(" ");
        }
    }

    // Return the reversed string
    return sb.toString();
}

