public static String reverseWords(String s) {
    // Check for null or empty input
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Initialize an empty string to store the reversed words
    String reversedWords = "";

    // Iterate over each word and reverse its characters
    for (String word : words) {
        // Check for null or empty word
        if (word == null || word.isEmpty()) {
            continue;
        }

        // Reverse the characters of the word and append it to the reversed string
        reversedWords += new StringBuilder(word).reverse().toString() + " ";
    }

    // Remove the trailing space if present
    if (reversedWords.endsWith(" ")) {
        reversedWords = reversedWords.substring(0, reversedWords.length() - 1);
    }

    return reversedWords;
}

